    25	const run = withAction<typeof createIssueSchema, Issue>(
    26	  createIssueSchema,
    27	  async (raw, actor) => {
    28	    const input = raw as CreateIssueInput;
    29	
    30	    const allowed = can(actor, "issue:create", {
    31	      kind: "issue",
    32	      orgId: input.orgId,
    33	      projectId: input.projectId,
    34	      issueId: "" as Issue["id"],
    35	      authorId: actor.userId,
    36	      assigneeId: input.assigneeId,
    37	    });
    38	    if (!allowed) {
    39	      throw new ForbiddenActionError("issue:create");
    40	    }
    41	
    42	    await assertProjectHasRoom(actor, input);
    43	
    44	    const issue = await createIssue(actor, input);
    45	
    46	    revalidateTagged(
    47	      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
    48	      CACHE_PROFILES.minutes,
    49	    );
    50	    return issue;
    51	  },
    52	  { revalidate: ["issues"], cacheProfile: "minutes" },
    53	);
    54	
    55	/**
    56	 * Counts the issues already living in the project and compares them with the
    57	 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
    58	 * which is why the count deliberately includes them.
    59	 */
    60	async function assertProjectHasRoom(
    61	  actor: Actor,
    62	  input: CreateIssueInput,
    63	): Promise<void> {
    64	  const summary = await getOrganizationSummary(actor, input.orgId);
    65	  const limits = getPlanLimits(summary.organization.plan);
    66	
    67	  const existing = await listIssues(actor, {
    68	    orgId: input.orgId,
    69	    projectId: input.projectId,
    70	    limit: 1,
    71	    includeArchived: true,
    72	  });
    73	
    74	  if (existing.total >= limits.issuesPerProject) {
    75	    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
    76	  }
    77	}
